/**
 * The fn.Hole.trace comparator (browser-safe): joins the branches' traces by geometric identity (contracts/s7.trace@1:
 * same badge, polylines within a 4 px ribbon of each other, ends within 4 px), names every disagreement, tabulates each
 * branch's judge, and emits legible frames:
 *   1. a ledger page: per branch reached / agreeing holes, bends hit / missed / extra, its overview raster
 *   2. one page per hole: a crop with every branch's polyline (its colour), Sam's corridor (dashed yellow) and bends
 *      (red crosses), the badge (white cross), with the legend and the per-branch numbers
 */
import { geometricJoin } from '../../fg/identity.mjs';
import { encodePngRgb, base64 } from '../../fg/png.mjs';
/** Sam's corridor line: tee -> bends -> basket; old schema (no bends): its centreline from the geometry-oriented edges. */
const samLine = (sam) => (!sam.bends && sam.centre ? sam.centre : [sam.tee, ...(sam.bends ?? []), sam.basket]);
import { HOLE_TRACE_SLOT, ACCEPTANCE, STATUS } from './traceSpace.mjs';

export const BRANCH_COLORS = Object.freeze({ s3first: [0, 230, 0], s3firstS4: [0, 200, 255], badgeOnly: [255, 140, 0], endpoints: [255, 0, 255], pinned: [160, 160, 255] });
export const STATUS_COLORS = Object.freeze({ agrees: [40, 220, 60], reachedDisagrees: [255, 150, 0], notReached: [255, 40, 40], unjudged: [80, 200, 255] });
export const SAM_COLOR = [255, 225, 25], SAM_BEND = [255, 0, 0], WHITE = [255, 255, 255];
export const LEGEND = "per-hole crops: one polyline per implementation (green s3first, cyan s3firstS4, orange badgeOnly, magenta endpoints, lilac pinned), small squares = its vertices (tee cap, bends, end); dashed yellow = Sam's corridor tee -> bends -> basket; red cross = Sam's bend; white cross = the hole's S1 badge centre. Overviews: polylines coloured by the judge (green agrees with Sam: ends at his basket and stays within W / 2 of his corridor; orange reaches a basket but disagrees; red reaches none; blue no testimony)";

/** Draw marks over a crop of the raster: region { x0, y0, w, h } at scale (any > 0), nearest sampling. */
export function drawCrop({ rgba, widthPx: IW, heightPx: IH }, { x0, y0, w, h, scale }, marks, { deflate } = {}) {
  const CW = Math.max(1, Math.round(w * scale)), CH = Math.max(1, Math.round(h * scale)), rgb = new Uint8Array(CW * CH * 3).fill(64);
  for (let Y = 0; Y < CH; Y++) for (let X = 0; X < CW; X++) {
    const sx = Math.floor(x0 + (X + 0.5) / scale), sy = Math.floor(y0 + (Y + 0.5) / scale);
    if (sx < 0 || sy < 0 || sx >= IW || sy >= IH) continue;
    const k = (sy * IW + sx) * 4, d = (Y * CW + X) * 3; rgb[d] = rgba[k]; rgb[d + 1] = rgba[k + 1]; rgb[d + 2] = rgba[k + 2];
  }
  const P = ([x, y]) => [(x - x0 + 0.5) * scale, (y - y0 + 0.5) * scale];
  const put = (X, Y, c) => { X = Math.round(X); Y = Math.round(Y); if (X < 0 || Y < 0 || X >= CW || Y >= CH) return; const d = (Y * CW + X) * 3; rgb[d] = c[0]; rgb[d + 1] = c[1]; rgb[d + 2] = c[2]; };
  const dot = (X, Y, c, r) => { for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) if (dx * dx + dy * dy <= r * r + 0.5) put(X + dx, Y + dy, c); };
  const seg = (a, b, c, width, dash) => {
    const [ax, ay] = P(a), [bx, by] = P(b), n = Math.max(1, Math.ceil(Math.hypot(bx - ax, by - ay)));
    for (let t = 0; t <= n; t++) { if (dash && Math.floor(t / dash) % 2) continue; dot(ax + (bx - ax) * t / n, ay + (by - ay) * t / n, c, width); }
  };
  for (const m of marks) {
    if (m.kind === 'line') for (let i = 1; i < m.pts.length; i++) seg(m.pts[i - 1], m.pts[i], m.color, m.width ?? 1, m.dash ?? 0);
    else if (m.kind === 'cross') { const [X, Y] = P(m.p), a = m.arm ?? 6; for (let d = -a; d <= a; d++) { dot(X + d, Y, m.color, 1); dot(X, Y + d, m.color, 1); } }
    else if (m.kind === 'square') { const [X, Y] = P(m.p), a = m.arm ?? 3; for (let d = -a; d <= a; d++) { put(X + d, Y - a, m.color); put(X + d, Y + a, m.color); put(X - a, Y + d, m.color); put(X + a, Y + d, m.color); } }
  }
  return { origin: [x0, y0], width: CW, height: CH, scale, png: base64(encodePngRgb({ width: CW, height: CH, rgb, ...(deflate ? { deflate } : {}) })) };
}

/** Marks for one judged hole: the polyline coloured by its verdict, its vertices, Sam's bends. */
export function judgedMarks(trace, row, sam, { width = 2 } = {}) {
  const color = !row?.judged ? STATUS_COLORS.unjudged : row.ok ? STATUS_COLORS.agrees : trace?.status === STATUS.reached ? STATUS_COLORS.reachedDisagrees : STATUS_COLORS.notReached;
  const out = [];
  if (sam) out.push({ kind: 'line', pts: samLine(sam), color: SAM_COLOR, width: 0, dash: 5 });
  if (trace?.path?.length > 1) out.push({ kind: 'line', pts: trace.path, color, width });
  for (const p of trace?.path ?? []) out.push({ kind: 'square', p, color, arm: 3 });
  for (const b of sam?.bends ?? []) out.push({ kind: 'cross', p: b, color: SAM_BEND, arm: 7 });
  return out;
}

export function compareTraces({ contract, parentStore, raster, deflate }) {
  return ({ branches, frame }) => {
    const names = Object.keys(branches).sort();
    const view = {};
    for (const n of names) {
      const b = branches[n], value = b.store?.has?.(HOLE_TRACE_SLOT.part) ? b.store.get(HOLE_TRACE_SLOT.part) : null;
      const judge = b.records?.[HOLE_TRACE_SLOT.testimony];
      view[n] = { error: b.error, value, traces: value?.traces ?? [], judge: judge?.status === 'held' ? judge : null };
    }
    const tp = parentStore.get('testimony.source.holePaths'), holesPart = parentStore.get('tk.s7.holes'), W = parentStore.get('tk.s7.hallway').widthPx;
    const samOf = (hole) => (tp.holes ?? []).find((h) => String(h.hole) === String(hole)) ?? null;
    const traced = (n) => view[n].traces.filter((t) => t.path.length >= 2).map((t) => ({ ...t, badgeLabel: t.hole }));
    const join = geometricJoin({ sets: Object.fromEntries(names.map((n) => [n, traced(n)])), contract });
    const perBranch = Object.fromEntries(names.map((n) => {
      const t = view[n].judge?.totals ?? null, tr = view[n].traces;
      return [n, { error: view[n].error?.message ?? null, rule: view[n].value?.rule ?? null, traces: tr.length, reached: tr.filter((x) => x.status === STATUS.reached).length,
        statuses: Object.fromEntries(Object.values(STATUS).map((s) => [s, tr.filter((x) => x.status === s).length])),
        judged: t?.judged ?? null, agree: t?.agree ?? null, reachedBasket: t?.reachedBasket ?? null, bendsSam: t?.bendsSam ?? null, bendsHit: t?.bendsHit ?? null, bendsMissed: t?.bendsMissed ?? null, extraBends: t?.extraBends ?? null,
        notAgreeing: t?.notAgreeing ?? [], rows: view[n].judge?.rows ?? [] }];
    }));
    // disagreements, named: per hole, the branches whose traces are not the same trace (contracts/s7.trace@1)
    const disagreements = [];
    for (const h of holesPart.holes) {
      const groups = join.identities.filter((id) => names.some((n) => id.members[n] !== null && traced(n)[id.members[n]].hole === h.hole))
        .map((id) => names.filter((n) => id.members[n] !== null && traced(n)[id.members[n]].hole === h.hole));
      const untraced = names.filter((n) => !traced(n).some((t) => t.hole === h.hole));
      if (groups.length > 1 || (groups.length && untraced.length)) disagreements.push({ hole: h.hole, sameTrace: groups.map((g) => g.join(' = ')), noPath: untraced });
    }
    // overview rasters: every branch's traces over the map, coloured by the judge
    const scale = Math.min(1, 640 / Math.max(raster.widthPx, raster.heightPx));
    const overview = (n) => drawCrop(raster, { x0: 0, y0: 0, w: raster.widthPx, h: raster.heightPx, scale },
      holesPart.holes.flatMap((h) => judgedMarks(view[n].traces.find((t) => t.hole === h.hole), perBranch[n].rows.find((r) => r.hole === h.hole), samOf(h.hole), { width: 1 })), { deflate });
    frame({
      title: `${HOLE_TRACE_SLOT.slot}: ${names.map((n) => `${n} ${perBranch[n].agree ?? '?'}/${perBranch[n].judged ?? '?'} agree, ${perBranch[n].reached} reach, bends ${perBranch[n].bendsHit ?? '?'}/${perBranch[n].bendsMissed ?? '?'}/${perBranch[n].extraBends ?? '?'}`).join('; ')}`,
      calculation: HOLE_TRACE_SLOT.slot,
      parts: [
        { address: `cmp.${HOLE_TRACE_SLOT.slot}.table`, kind: 'ledger', data: { rows: names.map((n) => ({ branch: n, traces: perBranch[n].traces, reached: perBranch[n].reached, judged: perBranch[n].judged, agree: perBranch[n].agree,
          bendsSam: perBranch[n].bendsSam, bendsHit: perBranch[n].bendsHit, bendsMissed: perBranch[n].bendsMissed, extraBends: perBranch[n].extraBends, notAgreeing: perBranch[n].notAgreeing.join(' '), error: perBranch[n].error })) } },
        { address: `cmp.${HOLE_TRACE_SLOT.slot}.disagreements`, kind: 'ledger', data: { rows: disagreements.map((d) => ({ hole: d.hole, sameTrace: d.sameTrace.join(' | '), noPath: d.noPath.join(' ') })) } },
        ...names.map((n) => ({ address: `cmp.${HOLE_TRACE_SLOT.slot}.overview.${n}`, kind: 'raster', data: overview(n) }))
      ],
      verdicts: names.map((n) => ({ name: `${n}: ${perBranch[n].agree ?? '?'} of ${perBranch[n].judged ?? '?'} judged holes agree with Sam`, ok: perBranch[n].judged != null && perBranch[n].agree === perBranch[n].judged })),
      receipt: { contract: join.contract, acceptance: ACCEPTANCE, legend: LEGEND, widthPx: W }
    });
    const pages = [];
    for (const h of holesPart.holes) {
      const sam = samOf(h.hole), pts = [...(sam ? [sam.tee, sam.basket, ...(sam.bends ?? []), ...(sam.centre ?? [])] : []), ...names.flatMap((n) => view[n].traces.find((t) => t.hole === h.hole)?.path ?? [])];
      if (!pts.length) continue;
      const xs = pts.map((p) => p[0]), ys = pts.map((p) => p[1]), m = W;
      const x0 = Math.floor(Math.min(...xs) - m), y0 = Math.floor(Math.min(...ys) - m), w = Math.ceil(Math.max(...xs) + m) - x0, hgt = Math.ceil(Math.max(...ys) + m) - y0;
      const scale = Math.min(2, 420 / Math.max(w, hgt));
      const marks = [];
      if (sam) marks.push({ kind: 'line', pts: samLine(sam), color: SAM_COLOR, width: 0, dash: 5 });
      for (const n of names) { const t = view[n].traces.find((x) => x.hole === h.hole); if (t?.path?.length > 1) { marks.push({ kind: 'line', pts: t.path, color: BRANCH_COLORS[n] ?? WHITE, width: 1 }); for (const p of t.path) marks.push({ kind: 'square', p, color: BRANCH_COLORS[n] ?? WHITE, arm: 3 }); } }
      for (const b of sam?.bends ?? []) marks.push({ kind: 'cross', p: b, color: SAM_BEND, arm: 8 });
      const crop = drawCrop(raster, { x0, y0, w, h: hgt, scale }, marks, { deflate });
      const rows = names.map((n) => {
        const t = view[n].traces.find((x) => x.hole === h.hole), r = perBranch[n].rows.find((x) => x.hole === h.hole);
        return { branch: n, status: t?.status ?? '-', agrees: r?.judged ? r.ok : null, why: r?.why ?? null, endBasket: t?.end?.basket ?? null, endErrPx: r?.endErrPx ?? null, maxOffCentrelinePx: r?.maxOffCentrelinePx ?? null,
          bends: t?.bends.length ?? null, bendsHit: r?.bendsHit ?? null, bendsMissed: r?.bendsMissed ?? null, extraBends: r?.extraBends ?? null, bendOffPx: (r?.bendOffPx ?? []).join(', '), how: t?.how ?? null, condition: t?.condition ?? null };
      });
      pages.push({ hole: h.hole, rows });
      const d = disagreements.find((x) => x.hole === h.hole);
      frame({
        title: `hole ${h.hole}: ${rows.map((r) => `${r.branch} ${r.status}${r.agrees === true ? ' agrees' : r.agrees === false ? ' disagrees' : ''}`).join(' | ')}${d ? `; different traces: ${d.sameTrace.join(' vs ')}` : ''}`,
        calculation: HOLE_TRACE_SLOT.slot,
        parts: [{ address: `cmp.${HOLE_TRACE_SLOT.slot}.crop.hole${h.hole}`, kind: 'raster', data: crop }, { address: `cmp.${HOLE_TRACE_SLOT.slot}.hole${h.hole}`, kind: 'ledger', data: { rows } }],
        verdicts: rows.map((r) => ({ name: `${r.branch}: ${r.status}${r.why ? ` (${r.why})` : ''}`, ok: r.agrees === true })),
        receipt: { legend: LEGEND, origin: crop.origin, scale: crop.scale, samCorridor: sam ? samLine(sam) : null, widthPx: W }
      });
    }
    return { slot: HOLE_TRACE_SLOT.slot, contract: join.contract, acceptance: ACCEPTANCE, widthPx: W, branches: perBranch, disagreements,
      matched: join.matched, only: join.only, partial: join.partial, collisions: join.collisions, ambiguous: join.ambiguous, holes: pages };
  };
}

/**
 * The S7 judge (browser-safe), one rule used by the testimony guarantee, the comparator and ports/judge (S7bends).
 *
 * Sam's S7 pass condition (docs/evidence/s7main/README.md): the trace ends at the hole's basket (its end within the
 * basket match rule, 12 px, of Sam's basket point) and its centreline never leaves the hallway: the largest distance
 * from Sam's corridor polyline tee -> bends -> basket is at most W / 2. Bend offsets are REPORTED, never gated:
 *   bendsHit     Sam's bends with one of ours within half his corridor width (closest pairs first, one to one)
 *   bendsMissed  Sam's bends with none of ours there
 *   extraBends   our bends matching none of Sam's
 * Testimony is impeachable; this is agreement, never acceptance. A hole without bend testimony (old schema) is unjudged.
 */
import { judgeTrace } from './hallway.mjs';

const r1 = (v) => (v == null ? null : Math.round(v * 10) / 10);
const dist = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1]);

/** One-to-one bend matching within radiusPx, closest pairs first. */
export function matchBends(sam, ours, radiusPx) {
  const pairs = [];
  sam.forEach((s, i) => ours.forEach((o, j) => { const d = dist(s, o); if (d <= radiusPx) pairs.push([d, i, j]); }));
  pairs.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2]);
  const ui = new Set(), uj = new Set(), hits = [];
  for (const [d, i, j] of pairs) if (!ui.has(i) && !uj.has(j)) { ui.add(i); uj.add(j); hits.push({ sam: i, ours: j, offPx: r1(d) }); }
  return { hits, missed: sam.map((_, i) => i).filter((i) => !ui.has(i)), extra: ours.map((_, j) => j).filter((j) => !uj.has(j)) };
}

/**
 * traces: px.holes.trace traces; holePaths: { holes: [{ hole, tee, basket, bends, corridorWidthPx }] } (canonical px);
 * widthPx: the course hallway width W (px, LOCAL).
 */
export function judgeHoleTraces(traces, holePaths, { widthPx, basketMatchPx = 12 }) {
  const rows = [];
  for (const p of holePaths.holes ?? []) {
    const t = traces.find((x) => String(x.hole) === String(p.hole));
    if (!p.bends && p.centre) {   // old schema: the route is judged against the corridor centreline; bends are unknown
      const sam = { tee: p.centre[0], basket: p.centre.at(-1), bends: p.centre.slice(1, -1) };
      if (!t || !t.path?.length || t.status !== 'reached') { rows.push({ hole: String(p.hole), judged: true, status: t?.status ?? 'missing', ok: false, why: `no BasketPoint reached (${t?.status ?? 'no trace'})`, reachedBasket: false, endErrPx: null, maxOffCentrelinePx: null, bendsSam: null, bendsOurs: (t?.bends ?? []).length, bendsJudged: false }); continue; }
      const j = judgeTrace({ verts: t.path, endPoint: t.end.point }, sam, widthPx, basketMatchPx);
      rows.push({ hole: String(p.hole), judged: true, status: t.status, ok: j.ok, why: j.ok ? null : j.endErrPx >= basketMatchPx ? `ends ${j.endErrPx} px from Sam's basket` : `leaves the hallway: ${j.maxDevPx} px from Sam's corridor centreline (W / 2 = ${j.halfWidthPx} px)`,
        reachedBasket: j.endErrPx < basketMatchPx, endErrPx: j.endErrPx, maxOffCentrelinePx: j.maxDevPx, halfWidthPx: j.halfWidthPx, bendsSam: null, bendsOurs: t.bends.length, bendsJudged: false,
        note: 'old annotation schema: route judged on the corridor centreline (edges oriented by geometry); bends not judged' });
      continue;
    }
    if (!p.bends) { rows.push({ hole: String(p.hole), judged: false, why: 'no bend testimony for this hole (old annotation schema)' }); continue; }
    const radius = (p.corridorWidthPx ?? widthPx) / 2;
    if (!t || !t.path?.length || t.status !== 'reached') {
      const m = matchBends(p.bends, t?.bends ?? [], radius);
      rows.push({ hole: String(p.hole), judged: true, status: t?.status ?? 'missing', ok: false, why: t?.status === 'reached' ? 'no path' : `no BasketPoint reached (${t?.status ?? 'no trace'})`,
        reachedBasket: false, endErrPx: null, maxOffCentrelinePx: null, bendsSam: p.bends.length, bendsOurs: (t?.bends ?? []).length,
        bendsHit: m.hits.length, bendsMissed: m.missed.length, extraBends: m.extra.length, bendMatchPx: r1(radius), bendOffPx: m.hits.map((h) => h.offPx) });
      continue;
    }
    const j = judgeTrace({ verts: t.path, endPoint: t.end.point }, p, widthPx, basketMatchPx);
    const m = matchBends(p.bends, t.bends, radius);
    rows.push({ hole: String(p.hole), judged: true, status: t.status, ok: j.ok, why: j.ok ? null : j.endErrPx >= basketMatchPx ? `ends ${j.endErrPx} px from Sam's basket` : `leaves the hallway: ${j.maxDevPx} px from Sam's corridor (W / 2 = ${j.halfWidthPx} px)`,
      reachedBasket: j.endErrPx < basketMatchPx, endErrPx: j.endErrPx, maxOffCentrelinePx: j.maxDevPx, halfWidthPx: j.halfWidthPx,
      bendsSam: p.bends.length, bendsOurs: t.bends.length, bendsHit: m.hits.length, bendsMissed: m.missed.length, extraBends: m.extra.length, bendMatchPx: r1(radius),
      bendOffPx: m.hits.map((h) => h.offPx), nearestBendOffPx: j.bendOffPx });
  }
  const J = rows.filter((r) => r.judged), sum = (k) => J.reduce((s, r) => s + (r[k] ?? 0), 0);
  return { rows, totals: { judged: J.length, agree: J.filter((r) => r.ok).length, reachedBasket: J.filter((r) => r.reachedBasket).length,
    bendsSam: sum('bendsSam'), bendsHit: sum('bendsHit'), bendsMissed: sum('bendsMissed'), extraBends: sum('extraBends'), notAgreeing: J.filter((r) => !r.ok).map((r) => r.hole) },
    rule: `ends within ${basketMatchPx} px of Sam's basket and stays within W / 2 = ${r1(widthPx / 2)} px of his corridor; a bend hits within half his corridor width` };
}

/**
 * The two FunctionalGuarantees every fn.Hole.trace fork-join branch runs (site 'forkjoin'; browser-safe).
 *
 *   fg.s7.holeTrace.materialize  one trace per hole (every S1 badge label exactly once); every vertex finite (one off the
 *     raster is recorded, not failed: a hidden tee's cap can lie beyond the frame); a reached trace ends on a named basket; the trace stays in the ribbon of its own legs (each walked
 *     leg's vertices are the polyline: nothing to leave) and no vertex is farther than W / 2 from the polyline through
 *     its neighbours' ribbon; written as an artifact with a frame
 *   fg.s7.holeTrace.testimony    judged against Sam's corridors (ports/s7trace/judgeBends.mjs): ends at his basket,
 *     stays within W / 2 of his corridor; bends hit / missed / extra reported. A judge, never a gate: findings are data.
 */
import { defineGuarantee } from '../../fg/guarantee.mjs';
import { HOLE_TRACE_SLOT, STATUS } from './traceSpace.mjs';
import { judgeHoleTraces } from './judgeBends.mjs';

const { part: PART, slot: SLOT } = HOLE_TRACE_SLOT;
const STATUSES = new Set(Object.values(STATUS));

export const materialize = defineGuarantee({
  id: HOLE_TRACE_SLOT.materialize,
  guards: [PART],
  reads: [PART, 'px.badges', 'px.image.cropped', 'tk.s7.hallway'],
  site: 'forkjoin',
  run(ctx) {
    const v = ctx.get(PART);
    if (!v || !Array.isArray(v.traces)) ctx.fail(`${PART} is not { traces: [...] }`);
    const badges = ctx.get('px.badges').map((b) => String(b.label)), img = ctx.get('px.image.cropped'), W = ctx.get('tk.s7.hallway').widthPx;
    const holes = v.traces.map((t) => String(t.hole));
    ctx.check('oneTracePerHole', badges.length === holes.length && badges.every((b) => holes.filter((h) => h === b).length === 1), { badges: badges.length, traces: holes.length });
    const bad = v.traces.filter((t) => !t.path.every((p) => Array.isArray(p) && p.length === 2 && p.every(Number.isFinite))).map((t) => t.hole);
    ctx.check('verticesFinite', bad.length === 0, { bad });
    // a vertex off the raster is data, not a failure: a hidden tee's predicted cap or a lost walk's end can lie beyond the frame
    const offRaster = v.traces.filter((t) => t.path.some((p) => p[0] < -0.5 || p[1] < -0.5 || p[0] > img.widthPx - 0.5 || p[1] > img.heightPx - 0.5)).map((t) => t.hole);
    ctx.check('statusesKnown', v.traces.every((t) => STATUSES.has(t.status)), { statuses: [...new Set(v.traces.map((t) => t.status))] });
    const noBasket = v.traces.filter((t) => t.status === STATUS.reached && !t.end?.basket).map((t) => t.hole);
    ctx.check('reachedEndsOnANamedBasket', noBasket.length === 0, { noBasket });
    // in the ribbon: a reached trace's end is its basket's point, and the polyline has no zero-length leg
    const degenerate = v.traces.filter((t) => t.path.some((p, i) => i && Math.hypot(p[0] - t.path[i - 1][0], p[1] - t.path[i - 1][1]) < 1e-6)).map((t) => t.hole);
    ctx.check('noDegenerateLeg', degenerate.length === 0, { degenerate });
    const counts = Object.fromEntries([...STATUSES].map((s) => [s, v.traces.filter((t) => t.status === s).length]));
    const artifact = ctx.artifact('traces', 'hole-traces-json', { schema: 'nctk-s7-hole-traces@1', slot: SLOT, part: PART, rule: v.rule, widthPx: W, scene: v.scene ?? null,
      frame: 'canonical (S0-cropped) px, pixel centres at integer coordinates', traces: v.traces, conditions: v.conditions ?? [] }, undefined, { path: 'traces.json' });
    ctx.frame({
      title: `${v.rule}: ${counts[STATUS.reached]} of ${v.traces.length} holes reach a basket (W = ${W} px)`, calculation: SLOT,
      parts: [
        { address: `${PART}#vertices`, kind: 'points', data: { points: v.traces.flatMap((t) => t.path.map((p, i) => [...p, `hole ${t.hole} v${i}`])) } },
        { address: `${PART}#ledger`, kind: 'ledger', data: { rows: v.traces.map((t) => ({ hole: t.hole, status: t.status, bends: t.bends.length, end: t.end?.basket ?? null, walkedPx: t.evidence?.walkedPx ?? null, meanPassFrac: t.evidence?.meanPassFrac ?? null, polyScoreLum: t.evidence?.polyScoreLum ?? null, how: t.how, condition: t.condition })) } },
        { address: `${PART}#artifact`, kind: 'scalar', artifact, data: { value: v.traces.length, unit: 'traces (one per hole)' } }
      ]
    });
    return { totals: { traces: v.traces.length, ...counts, bends: v.traces.reduce((s, t) => s + t.bends.length, 0), offRaster: offRaster.length }, offRasterHoles: offRaster, widthPx: W };
  }
});

export const testimony = defineGuarantee({
  id: HOLE_TRACE_SLOT.testimony,
  guards: [PART],
  reads: [PART, 'testimony.source.holePaths', 'tk.s7.hallway'],
  requires: [HOLE_TRACE_SLOT.materialize],
  site: 'forkjoin',
  run(ctx) {
    const v = ctx.get(PART), tp = ctx.get('testimony.source.holePaths'), W = ctx.get('tk.s7.hallway').widthPx;
    const j = judgeHoleTraces(v.traces, tp, { widthPx: W, basketMatchPx: HOLE_TRACE_SLOT.basketMatchPx });
    ctx.check('everyAnnotatedHoleJudgedOnce', j.rows.length === (tp.holes ?? []).length, { rows: j.rows.length });
    ctx.frame({
      title: `${v.rule} vs Sam: ${j.totals.agree} of ${j.totals.judged} judged holes agree; bends ${j.totals.bendsHit} hit / ${j.totals.bendsMissed} missed / ${j.totals.extraBends} extra`,
      calculation: SLOT,
      parts: [
        { address: 'testimony.bends', kind: 'points', data: { points: (tp.holes ?? []).flatMap((h) => (h.bends ?? []).map((b) => [...b, `Sam bend, hole ${h.hole}`])) } },
        { address: `${PART}#judge`, kind: 'ledger', data: { rows: j.rows.map((r) => ({ ...r, bendOffPx: (r.bendOffPx ?? []).join(', '), nearestBendOffPx: (r.nearestBendOffPx ?? []).join(', ') })) } }
      ],
      verdicts: j.rows.filter((r) => r.judged).map((r) => ({ name: `hole ${r.hole}: ${r.ok ? 'agrees' : r.why}`, ok: r.ok })),
      receipt: { rule: j.rule, testimonyRule: tp.rule }
    });
    return { totals: j.totals, rows: j.rows, rule: j.rule };
  }
});

export const GUARANTEES = [materialize, testimony];
